207	// makeTestJWT builds a three-segment JWT (alg:HS256 so ParseClaims accepts it)
208	// carrying the given aud. The signature segment is filler — the env-token path
209	// reads the aud unverified and gates it on cluster-advertised cores, never on
210	// the signature.
211	func makeTestJWT(t *testing.T, aud string) string {
212		t.Helper()
213		enc := base64.RawURLEncoding
214		header := enc.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
215		payload := enc.EncodeToString([]byte(fmt.Sprintf(`{"sub":"ci-runner","aud":%q}`, aud)))
216		return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
217	}
