219	// wellKnownServer serves /.well-known/entire-cluster.json advertising the
220	// given cores, jurisdiction audience, and jurisdiction core over TLS,
221	// returning the server and the host:port to use as clusterHost. An empty
222	// audience models a cluster predating jurisdiction-token git auth.
223	func wellKnownServer(t *testing.T, cores []string, jurisdictionAudience, jurisdictionCoreURL string) (*httptest.Server, string) {
224		t.Helper()
225		srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
226			if r.URL.Path != "/.well-known/entire-cluster.json" {
227				http.NotFound(w, r)
228				return
229			}
230			body := map[string]any{"core_urls": cores}
231			if jurisdictionAudience != "" {
232				body["jurisdiction_audience"] = jurisdictionAudience
233			}
234			if jurisdictionCoreURL != "" {
235				body["jurisdiction_core_url"] = jurisdictionCoreURL
236			}
237			_ = json.NewEncoder(w).Encode(body) //nolint:errcheck // best-effort in test stub
238		}))
239		t.Cleanup(srv.Close)
240		u, err := url.Parse(srv.URL)
241		if err != nil {
242			t.Fatalf("parse server URL: %v", err)
243		}
244		return srv, u.Host
245	}
